def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 100:
        return 'C'

    my_score = 0
    opp_score = 0
    for a, b in history:
        if a == 'C' and b == 'C':
            my_score += 3
            opp_score += 3
        elif a == 'C' and b == 'D':
            my_score += 0
            opp_score += 5
        elif a == 'D' and b == 'C':
            my_score += 5
            opp_score += 0
        else:
            my_score += 1
            opp_score += 1

    def coop_rate(start):
        cnt = 0
        tot = n - start
        if tot <= 0:
            return 0.5
        for i in range(start, n):
            if history[i][1] == 'C':
                cnt += 1
        return cnt / tot

    recent_len = min(12, n)
    recent_opp = coop_rate(n - recent_len)
    overall_opp = coop_rate(0)

    last_me, last_opp = history[-1]

    defection_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            defection_streak += 1
        else:
            break

    cooperation_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'C':
            cooperation_streak += 1
        else:
            break

    score_diff = my_score - opp_score
    rounds_left = 100 - n

    if n == 1:
        if last_opp == 'D':
            return 'D'
        return 'C'

    if recent_opp <= 0.15 and defection_streak >= 2:
        return 'D'

    if rounds_left <= 2:
        if last_opp == 'C' and recent_opp > 0.4:
            return 'D'
        if last_opp == 'D':
            return 'D'
        return 'C'

    if rounds_left <= 7:
        if recent_opp >= 0.7:
            if rng.random() < 0.5:
                return 'D'
            return 'C'
        if recent_opp <= 0.35:
            return 'D'
        if last_opp == 'D':
            return 'D'
        return 'C'

    if n >= 4 and defection_streak >= 3:
        if rng.random() < 0.88:
            return 'D'
        return 'C'

    if overall_opp >= 0.8 and recent_opp >= 0.6:
        if cooperation_streak >= 8 and rounds_left > 15 and rng.random() < 0.05:
            return 'D'
        return 'C'

    if n >= 2:
        prev_me, prev_opp = history[-2]
        if last_opp == 'C' and prev_opp == 'C' and overall_opp >= 0.7:
            if rng.random() < 0.06 and rounds_left > 20:
                return 'D'
            return 'C'

    if last_opp == 'C' and recent_opp >= 0.6:
        return 'C'

    if overall_opp >= 0.75 and recent_opp >= 0.5:
        return 'C'

    if last_opp == 'D':
        if recent_opp >= 0.55:
            if rng.random() < 0.7:
                return 'C'
            return 'D'
        if defection_streak >= 3:
            if rng.random() < 0.85:
                return 'D'
            return 'C'
        if defection_streak >= 2:
            if rng.random() < 0.7:
                return 'D'
            return 'C'
        if rng.random() < 0.55:
            return 'D'
        return 'C'

    if recent_opp >= 0.5:
        return 'C'

    if recent_opp < 0.35:
        if score_diff < -5:
            return 'D'
        if rng.random() < 0.35:
            return 'D'
        return 'C'

    return 'C'
